// Map each selected catalog_line (sent by the app in the webhook body) to the
// Hermes item shape. Hermes inserts by EAN: a NEW ean is created, an EXISTING
// ean is ignored (no update, no duplicate) — so we just send everything selected.
// Field mapping is the confirmed one.
//
// EAN: the catalog stores a 13-digit EAN, but Hermes wants the barcode WITHOUT the
// catalog's leading zero — a 13-digit EAN starting with 0 is sent as 12 digits
// (0075678581519 -> 075678581519). Only the first zero is dropped; a non-zero 13-digit
// EAN or an already-12-digit one is sent unchanged (Hermes accepts 12 or 13).
const hermesEan = (v) => {
  const s = String(v ?? '').replace(/[^0-9]/g, '');
  if (!s) return null;
  return (s.length === 13 && s[0] === '0') ? s.slice(1) : s;
};
const lines = $('Webhook').first().json.body?.lines ?? [];
return lines.map(l => ({ json: {
  _line_id: l.id,
  _ean: l.ean ?? null,
  item: {
    title: l.title ?? null,
    author: l.artist ?? null,
    releaseDate: l.release_date ?? null,
    format: l.format ?? null,
    ean: hermesEan(l.ean),
    calculationGroup: l.calculation_group ?? null,
    supplierCode: l.supplier_code ?? null,
  },
} }));

// Map Sent — write the Hermes MblaID back into Supabase as hermes_id.
//
// Hermes /api/productsCatalogue response (confirmed from live sends) is an array
// with one object: { message, return_description, return_value, status }.
//   * Inserted (status 1): return_value is a JSON *string* array of
//       [{ EAN: '075678581540', MblaID: 70463 }, ...]  <- the id we want.
//   * Already-existing (status 0): return_value is pipe-delimited text
//       ('Item with EAN = ... already exists ... Skipping insertion.') with NO
//       MblaID — those rows keep whatever hermes_id they already had.
// Mixed batches can contain both, so we capture every MblaID we can parse and
// fall back to the line's current hermes_id when Hermes returned none (so we
// never clobber an id, e.g. on historical rows already known to Hermes).

// 1) Gather the response object(s) however n8n surfaced the top-level array.
const responses = [];
for (const it of $('Hermes POST Catalogue').all()) {
  const j = it.json;
  if (Array.isArray(j)) responses.push(...j);
  else if (j && Array.isArray(j.body)) responses.push(...j.body);
  else if (j) responses.push(j);
}

// 2) Build EAN -> MblaID from every parseable JSON return_value.
const normEan = v => String(v ?? '').replace(/[^0-9]/g, '').replace(/^0+/, '');
const idByEan = new Map();
for (const r of responses) {
  let rv = r && r.return_value;
  if (rv == null) continue;
  if (typeof rv === 'string') {
    const s = rv.trim();
    if (!(s.startsWith('[') || s.startsWith('{'))) continue; // plain-text skips
    try { rv = JSON.parse(s); } catch (e) { continue; }
  }
  for (const row of (Array.isArray(rv) ? rv : [rv])) {
    const ean = row && (row.EAN ?? row.ean);
    const id  = row && (row.MblaID ?? row.mblaId ?? row.mbla_id ?? row.id);
    // Hermes returns MblaID 0 on single-item inserts (the real id is assigned later, if at all) -> skip it; never store '0'.
    if (ean != null && id != null && Number(id) !== 0) idByEan.set(normEan(ean), String(id));
  }
}

// 3) Current hermes_id per line, straight from the webhook payload (select * ).
const existingById = new Map(
  ($('Webhook').first().json.body?.lines ?? []).map(l => [String(l.id), l.hermes_id ?? null])
);

// 4) One row per submitted line for the writeback.
const meta = $('Prepare Items').all().map(i => ({ line_id: i.json._line_id, ean: i.json._ean }));
return meta.map(m => ({ json: {
  id: m.line_id,
  hermes_id: idByEan.get(normEan(m.ean)) ?? existingById.get(String(m.line_id)) ?? null,
} }));
